typedef struct xmqttalias {size_t Size,Capacity;char Topic[];} xmqttalias;
enum {XMQTT_TX_ALIAS=8,XMQTT_TX_FENCE=16,XMQTT_TX_SESSION=32,XMQTT_TX_BORROW=64,XMQTT_TX_SHARED=128};
