        if(!R || R->Type!=Expected || R->Offset!=xmqttRequestWireBytes(R) || (!C->ProblemInfo && P->Properties.Count)){
            xmqttClientFail(C,XMQTT_STATUS_PROTOCOL,NULL);return false;}
