    const unsigned char* Data[3]={A->Prefix,(const unsigned char*)A->Topic->Data,R->Wire+A->TailOffset};
    size_t Sizes[3]={A->PrefixBytes,A->Mode==3?A->Topic->Size:0,R->Bytes-A->TailOffset};
