    if(P->ReadyNext)P->ReadyNext->ReadyPrevious=P->ReadyPrevious;else S->ReadyTail[K]=P->ReadyPrevious;
    P->ReadyKind=0;P->ReadyNext=P->ReadyPrevious=NULL;
