    if(S->ExpectedId.Size&&S->Info.ClientId.Data==S->ExpectedId.Data){S->ExpectedId=(xstrview){0};S->Config.ClientId=S->Info.ClientId;}
    S->Info.LiveAtCut=S->Live;S->Info.RemainingMilliseconds=0;
